<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { useGameSession } from '@/stores/gameSession'
import { createRoom, getAllRooms, joinRoom } from '@/api/rooms'
import { getWarlordsHub, upgradeWarlords, selectWarlordsHero } from '@/api/warlords'
import type { WarlordsHub } from '@/types/warlords'
import { heroLevel } from '@/types/warlords'
import type { GameRoom } from '@/types/game'
import WarlordsMap from '@/components/warlords/WarlordsMap.vue'
import WarlordsCamp from '@/components/warlords/WarlordsCamp.vue'
import WarlordsHeroes from '@/components/warlords/WarlordsHeroes.vue'
import WarlordsAccount from '@/components/warlords/WarlordsAccount.vue'
import WarlordPortrait from '@/components/warlords/WarlordPortrait.vue'
import WarlordsFormations from '@/components/warlords/WarlordsFormations.vue'
import WarlordsHistory from '@/components/warlords/WarlordsHistory.vue'
import '@/game/warlords.css'
const router=useRouter()
const session=useGameSession()
const hub=ref<WarlordsHub|null>(null)
const rooms=ref<GameRoom[]>([])
const selected=ref(1)
const error=ref('')
const notice=ref('')
const loading=ref(true)
const busy=ref(false)
const refreshingRooms=ref(false)
const roomsError=ref('')
let poll:number|undefined
let disposed=false
const chapter=computed(()=>hub.value?.chapters.find(item=>item.id===selected.value))
const selectedHero=computed(()=>hub.value?.heroes.find(hero=>hero.id===hub.value?.profile.heroId))
const level=computed(()=>hub.value?heroLevel(hub.value.profile):1)
const campaignComplete=computed(()=>!!hub.value&&hub.value.chapters.every(chapter=>hub.value!.profile.cleared.includes(chapter.id)))
const campaignProgress=computed(()=>hub.value?Math.round(hub.value.profile.cleared.length/Math.max(1,hub.value.chapters.length)*100):0)
const chapterCleared=computed(()=>!!hub.value&&!!chapter.value&&hub.value.profile.cleared.includes(chapter.value.id))
const duelRooms=computed(()=>rooms.value.filter(room=>room.gameType==='WARLORDS_DUEL'&&
  (room.status==='WAITING'&&room.players.length<room.maxPlayers || room.status==='IN_PROGRESS'&&room.players.some(p=>p.id===session.player.id))))
async function refreshRooms(){
  if(refreshingRooms.value)return
  refreshingRooms.value=true
  try{const next=await getAllRooms();if(!disposed){rooms.value=next;roomsError.value=''}}
  catch{if(!disposed)roomsError.value='Chưa tải được danh sách bàn. Hãy làm mới để thử lại.'}
  finally{if(!disposed)refreshingRooms.value=false}
}
async function load(){
  error.value='';loading.value=true
  try{const next=await getWarlordsHub();if(disposed)return;hub.value=next;selected.value=Math.min(next.profile.unlocked,next.chapters.length);await refreshRooms()}
  catch(cause){if(!disposed)error.value=cause instanceof Error?cause.message:'Không thể tải chiến dịch.'}
  finally{if(!disposed)loading.value=false}
}
onMounted(()=>{void load();poll=window.setInterval(refreshRooms,5000)})
onUnmounted(()=>{disposed=true;window.clearInterval(poll)})
async function enter(mode:'CAMPAIGN'|'DUEL'){
  if(busy.value||loading.value)return
  if(mode==='CAMPAIGN'&&(!hub.value||!chapter.value||chapter.value.id>hub.value.profile.unlocked))return
  busy.value=true;error.value=''
  try{
    const type=mode==='CAMPAIGN'?'WARLORDS_CAMPAIGN':'WARLORDS_DUEL'
    const existing=rooms.value.find(room=>room.gameType===type&&room.hostId===session.player.id&&['WAITING','IN_PROGRESS'].includes(room.status))
    const room=existing??await createRoom({name:mode==='CAMPAIGN'?'Sơn Hà · Hành trình Hoa Lư':`Đấu tướng · ${session.player.username}`,
      gameType:type,maxPlayers:mode==='CAMPAIGN'?1:2})
    session.setCurrentRoom(room)
    await router.push({path:`/room/${room.id}`,query:mode==='CAMPAIGN'?{chapter:selected.value}:{}})
  }catch(cause){error.value=cause instanceof Error?cause.message:'Không thể tạo bàn chơi.'}
  finally{busy.value=false}
}
async function join(room:GameRoom){
  if(busy.value||loading.value)return
  busy.value=true;error.value=''
  try{const updated=await joinRoom(room.id,{playerId:session.player.id,username:session.player.username,sessionId:session.player.sessionId});session.setCurrentRoom(updated);await router.push(`/room/${room.id}`)}
  catch{error.value='Không thể vào bàn. Phòng có thể đã đầy hoặc trận đã bắt đầu.';void refreshRooms()}
  finally{busy.value=false}
}
async function upgrade(type:string){
  if(busy.value||loading.value||!hub.value)return
  busy.value=true;error.value='';notice.value=''
  try{hub.value={...hub.value,profile:await upgradeWarlords(type)};notice.value='Nâng cấp thành công. Đội quân đã sẵn sàng!'}
  catch(cause){error.value=cause instanceof Error?cause.message:'Không thể nâng cấp.'}
  finally{busy.value=false}
}
async function selectHero(heroId:string){
  if(busy.value||loading.value||!hub.value||hub.value.profile.heroId===heroId)return
  busy.value=true;error.value='';notice.value=''
  try{hub.value={...hub.value,profile:await selectWarlordsHero(heroId)};notice.value='Đã chọn tướng. Lựa chọn được lưu cho trận tiếp theo.'}
  catch(cause){error.value=cause instanceof Error?cause.message:'Không thể chọn tướng.'}
  finally{busy.value=false}
}
</script>
<template>
  <div class="warlords warlords-hub">
    <header class="war-header"><span class="war-eyebrow">BRIM ORIGINAL · MATCH-3 CHIẾN THUẬT</span><button class="war-button secondary small" @click="router.push('/')">← Về đấu trường</button></header>
    <section class="hub-intro" aria-labelledby="son-ha-title"><div class="hub-intro-copy"><span class="intro-kicker"><i/> MỘT HÀNH TRÌNH TỪ HOA LƯ</span><h1 id="son-ha-title">SƠN HÀ<em>Hợp cờ Hoa Lư</em></h1><p>Ghép thế trận. Dẫn quân qua mười hai chương.<br/>Viết tiếp hành trình dưới ngọn cờ của bạn.</p><div class="intro-actions"><a class="war-button" href="#warlords-campaign">{{ campaignComplete?'Chinh phục lại chiến dịch':'Khám phá chiến dịch' }} <span aria-hidden="true">↓</span></a><a class="intro-duel" href="#warlords-duel">Đấu tướng cùng bạn <span aria-hidden="true">↗</span></a></div></div><div class="hub-intro-art" aria-hidden="true"><div class="intro-sun"/><svg viewBox="0 0 340 280"><path d="M0 220 50 170 80 192 138 122 174 161 206 111 258 171 302 144 340 197V280H0Z" fill="#667162" opacity=".25"/><path d="m0 254 42-48 42 31 35-44 34 17 46-38 61 54 42-28 38 31v51H0Z" fill="#243e3b"/><path d="M225 37v215M226 39h64l-19 31 19 29h-64" fill="#8c3e31" stroke="#d1a86a" stroke-width="3"/><path d="m242 59 12-10 13 10-13 12Z" fill="none" stroke="#d8b477" stroke-width="2"/><path d="M20 270q120-55 215-10t105 5" fill="none" stroke="#b59c6740" stroke-width="2"/></svg><WarlordPortrait :hero="selectedHero"/><span class="intro-art-caption">{{ selectedHero?.name??'Ngọn cờ Hoa Lư' }}<small>{{ selectedHero?.title??'Hành trình hợp cờ' }}</small></span></div></section>
    <p v-if="error" class="war-error" role="alert">{{ error }}</p>
    <p v-if="notice" class="war-notice" role="status">{{ notice }}</p>
    <div v-if="loading" class="hub-loading war-panel" role="status"><span class="loading-seal" aria-hidden="true">⚑</span><div><strong>Đang mở doanh trại…</strong><p class="war-muted">Chuẩn bị tướng, quân đoàn và lộ trình của bạn.</p></div></div>
    <button v-else-if="!hub" class="war-button" @click="load">Thử tải lại</button>
    <template v-if="hub">
      <section class="hub-overview" aria-label="Tổng quan quân đoàn"><div class="overview-player"><span class="overview-monogram" aria-hidden="true">{{ session.player.username.charAt(0).toUpperCase() }}</span><span><small>QUÂN ĐOÀN CỦA</small><strong>{{ session.player.username }}</strong></span></div><div><span class="overview-icon" aria-hidden="true">◈</span><span><strong>{{ hub.profile.gold.toLocaleString('vi-VN') }}</strong><small>Vàng hiện có</small></span></div><div><span class="overview-icon" aria-hidden="true">✦</span><span><strong>Cấp {{ level }}</strong><small>{{ level===20?'Đạt cấp tối đa':`${100-hub.profile.experience%100} XP đến cấp tiếp` }}</small></span></div><div><span class="overview-icon" aria-hidden="true">⚑</span><span><strong>{{ hub.profile.cleared.length }} / {{ hub.chapters.length }}</strong><small>Chương hoàn thành</small></span></div><div><span class="overview-icon" aria-hidden="true">⚔</span><span><strong>{{ hub.profile.wins }} thắng</strong><small>{{ hub.profile.losses }} trận thua</small></span></div></section>
      <WarlordsAccount :disabled="busy||loading" @busy="busy=$event" @changed="load"/>
      <section v-if="hub.savedCampaign" class="war-panel resume-campaign"><div><strong>Chiến dịch đã lưu · Chương {{hub.savedCampaign.chapter}}</strong><p class="war-muted">{{hub.savedCampaign.phase==='BATTLE'?'Tiếp tục bàn cờ và đội quân ở lượt đã lưu gần nhất.':'Xem lại kết quả trận gần nhất rồi tiếp tục hành trình.'}}</p></div><button class="war-button" :disabled="busy" @click="enter('CAMPAIGN')">{{hub.savedCampaign.phase==='BATTLE'?'Tiếp tục trận':'Xem kết quả'}}</button></section>
      <WarlordsHeroes :heroes="hub.heroes" :selected="hub.profile.heroId" :busy="busy||loading" @select="selectHero"/>
      <div id="warlords-campaign" class="campaign-section-heading"><div><span class="war-eyebrow">{{ campaignComplete?'CHIẾN DỊCH HOÀN TẤT':'TỪ HOA LƯ, MỞ LỐI SƠN HÀ' }}</span><h2>{{ campaignComplete?'Mười hai chương, một ngọn cờ':'Chọn chương. Chuẩn bị xuất quân.' }}</h2><p>{{ campaignComplete?'Bạn có thể trở lại các chương để thử một phong cách tướng mới.':'Chọn một địa danh đã mở để xem đối thủ và phần thưởng.' }}</p></div><div class="campaign-completion"><span>{{ campaignProgress }}% hành trình</span><progress :value="hub.profile.cleared.length" :max="hub.chapters.length" aria-label="Tiến độ hoàn thành chiến dịch"/></div></div>
      <div class="war-campaign-layout">
        <WarlordsMap :chapters="hub.chapters" :profile="hub.profile" :selected="selected" :disabled="busy||loading" @select="selected=$event"/>
        <aside class="war-sidebar">
          <section v-if="chapter" class="war-panel chapter-detail" aria-labelledby="selected-chapter-title"><div class="chapter-detail-top"><span class="war-eyebrow">CHƯƠNG {{ String(chapter.id).padStart(2,'0') }} / {{ hub.chapters.length }}</span><span class="chapter-state" :class="{ completed:chapterCleared }">{{ chapterCleared?'✓ Đã hoàn thành':'⚑ Sẵn sàng xuất quân' }}</span></div><span class="chapter-place">{{ chapter.location }}</span><h2 id="selected-chapter-title">{{ chapter.title }}</h2><strong class="chapter-warlord">{{ chapter.warlord }} <span>· {{ chapter.encounter }}</span></strong><p>{{ chapter.story }}</p>
            <div class="chapter-enemy"><span><small>HP ĐỐI THỦ</small><strong>{{ chapter.enemyHp }}</strong></span><span><small>CÔNG / KIẾM</small><strong>{{ chapter.enemyAttack }}</strong></span><span><small>CẤP CHIẾN THUẬT</small><strong>{{ chapter.botLevel }} <em>/ 4</em></strong></span></div>
            <p class="chapter-bot-style"><span aria-hidden="true">{{ '◆'.repeat(chapter.botLevel) }}{{ '◇'.repeat(4-chapter.botLevel) }}</span>{{ chapter.botStyle }}</p>
            <div class="chapter-rewards"><small>THƯỞNG CHIẾN THẮNG</small><span>◈ {{ chapter.gold }} vàng</span><span>✦ {{ chapter.experience }} XP</span></div>
            <p v-if="!chapterCleared" class="first-clear"><span aria-hidden="true">✧</span> Lần đầu qua chương: <strong>+50 vàng · +30 XP</strong></p><p v-else class="replay-note">Có thể chơi lại để nhận thưởng trận và chiến lợi phẩm.</p>
            <button class="war-button" :disabled="busy||loading||chapter.id>hub.profile.unlocked" @click="enter('CAMPAIGN')">{{ busy?'Đang chuẩn bị…':chapterCleared?`Chơi lại chương ${chapter.id} →`:`Vào chương ${chapter.id} →` }}</button>
            <p class="chapter-action-note">Vàng và quân thư ghép được cộng vào chiến lợi phẩm cuối trận.</p>
          </section>
          <WarlordsCamp :profile="hub.profile" :hero="selectedHero" :busy="busy||loading" @upgrade="upgrade"/>
        </aside>
      </div>
      <section id="warlords-duel" class="war-panel duel-panel">
        <span class="duel-emblem" aria-hidden="true">⚔</span><div><span class="war-eyebrow">ĐẤU TƯỚNG · PVP TRỰC TUYẾN</span><h2>Gặp nhau trên cùng một thế trận</h2><p>Tạo bàn, gửi link mời bạn và luân phiên ra đòn trên bàn 8×8.</p><div class="duel-fair-stats"><span>140 HP</span><span>5 công / kiếm</span><span>Chỉ số ngang nhau</span></div></div>
        <button class="war-button" :disabled="busy||loading" @click="enter('DUEL')">Tạo bàn đấu tướng →</button>
      </section>
      <div class="war-section-header"><h2>Bàn đấu đang mở <span class="room-count">{{ duelRooms.length }}</span></h2><button class="war-button secondary small" :disabled="refreshingRooms||busy" @click="refreshRooms">{{ refreshingRooms?'Đang tải…':'↻ Làm mới' }}</button></div>
      <p v-if="roomsError" class="war-error" role="status">{{ roomsError }}</p>
      <div class="duel-room-list" :aria-busy="refreshingRooms"><article v-for="room in duelRooms" :key="room.id" class="war-panel duel-room"><span class="room-emblem" aria-hidden="true">⚔</span><div><strong>{{ room.name }}</strong><span class="war-muted"><i/>{{ room.players.length }}/2 người · {{ room.status==='WAITING'?'Chờ đối thủ':'Đang chơi' }}</span></div><button class="war-button small" :disabled="busy" @click="join(room)">{{ room.status==='IN_PROGRESS'?'Vào lại':'Vào bàn' }}</button></article><div v-if="!duelRooms.length&&!roomsError" class="empty-duel war-panel"><span aria-hidden="true">⚑</span><div><strong>Thế trận đang chờ bạn</strong><p>Chưa có bàn đấu phù hợp. Tạo bàn mới và gửi link mời một người bạn.</p></div></div></div>
      <details class="rules-panel war-panel"><summary>Cách chơi Sơn Hà · quân đặc biệt & liên hoàn</summary><p>Đổi hai ô kề nhau để ghép ít nhất 3 tài nguyên cùng loại. Kiếm gây sát thương; năng lượng dùng kỹ năng; tim hồi HP; khiên đỡ đòn; vàng và quân thư là chiến lợi phẩm nhận khi trận kết thúc. Ghép 4, 5 hoặc hình T/L tạo quân đặc biệt theo bảng dưới.</p><WarlordsFormations/><p>Mỗi lần đổi hợp lệ hoặc dùng kỹ năng tiêu tốn một lượt. Nước không tạo bộ ba và không kích hoạt quân đặc biệt không mất lượt. Các quân đặc biệt nằm trên bàn chung, cả hai bên đều có thể dùng; quân vừa tạo chỉ kích hoạt từ đợt liên hoàn tiếp theo hoặc khi được dùng ở lượt sau.</p><p>Từ lượt 40, quân vừa hành động mất dần HP do hao quân. Mỗi lượt có 45 giây; quá giờ mất 12 HP và đổi lượt, bỏ ba lượt liên tiếp sẽ thua. Bàn PvP có bot là luyện tập, không thưởng vàng/XP.</p></details>
      <WarlordsHistory/>
      <p class="war-history-note">Chiến dịch hư cấu lấy cảm hứng từ nhân vật, địa danh thời 12 sứ quân. Thứ tự màn không phải niên biểu; các trận thao luyện không có nghĩa nhân vật ấy bị tiêu diệt. <a href="https://baotanglichsuquocgia.vn/vi/Articles/3096/14529/tam-nhin-chien-luoc-cua-djinh-bo-linh.html" target="_blank" rel="noopener noreferrer">Đọc bối cảnh tại Bảo tàng Lịch sử quốc gia ↗</a></p>
    </template>
  </div>
</template>
<style scoped>
.resume-campaign{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:16px;border-color:#9eb77b77}.resume-campaign p{font-size:.78rem;margin-bottom:0}.resume-campaign>button{white-space:nowrap}@media(max-width:600px){.resume-campaign{align-items:stretch;flex-direction:column}}
